// Package grpc contains the inbound ConnectRPC adapter for the crop-service.
// NOTE: proto types are generated by buf generate.
package grpc

import (
	"context"

	"connectrpc.com/connect"
	"p9e.in/samavaya/packages/errors"
	"p9e.in/samavaya/packages/p9context"
	"p9e.in/samavaya/packages/p9log"

	// Generated by buf generate
	pb "p9e.in/samavaya/agriculture/crop-service/api/v1"
	"p9e.in/samavaya/agriculture/crop-service/api/v1/cropv1connect"
	"p9e.in/samavaya/agriculture/crop-service/internal/domain"
	"p9e.in/samavaya/agriculture/crop-service/internal/ports/inbound"
)

// CropHandler is the ConnectRPC inbound adapter.
type CropHandler struct {
	cropv1connect.UnimplementedCropServiceHandler
	svc inbound.CropService
	log *p9log.Helper
}

// NewCropHandler creates a new ConnectRPC crop handler.
func NewCropHandler(svc inbound.CropService, log p9log.Logger) *CropHandler {
	return &CropHandler{
		svc: svc,
		log: p9log.NewHelper(p9log.With(log, "component", "CropHandler")),
	}
}

// CreateCrop handles creation requests.
func (h *CropHandler) CreateCrop(ctx context.Context, req *connect.Request[pb.CreateCropRequest]) (*connect.Response[pb.CreateCropResponse], error) {
	h.log.Infow("msg", "CreateCrop request", "tenant_id", p9context.TenantID(ctx))
	if req.Msg.GetName() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "name is required")
	}
	entity := &domain.Crop{Name: req.Msg.GetName()}
	created, err := h.svc.CreateCrop(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.CreateCropResponse{Crop: cropToProto(created)}), nil
}

// GetCrop handles get requests.
func (h *CropHandler) GetCrop(ctx context.Context, req *connect.Request[pb.GetCropRequest]) (*connect.Response[pb.GetCropResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity, err := h.svc.GetCrop(ctx, req.Msg.GetId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.GetCropResponse{Crop: cropToProto(entity)}), nil
}

// ListCrops handles list requests.
func (h *CropHandler) ListCrops(ctx context.Context, req *connect.Request[pb.ListCropsRequest]) (*connect.Response[pb.ListCropsResponse], error) {
	params := domain.ListCropParams{PageSize: req.Msg.GetPageSize()}
	entities, total, err := h.svc.ListCrops(ctx, params)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	protos := make([]*pb.Crop, 0, len(entities))
	for i := range entities {
		protos = append(protos, cropToProto(&entities[i]))
	}
	return connect.NewResponse(&pb.ListCropsResponse{Crops: protos, TotalCount: total}), nil
}

// UpdateCrop handles update requests.
func (h *CropHandler) UpdateCrop(ctx context.Context, req *connect.Request[pb.UpdateCropRequest]) (*connect.Response[pb.UpdateCropResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	entity := &domain.Crop{}
	entity.UUID = req.Msg.GetId()
	updated, err := h.svc.UpdateCrop(ctx, entity)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.UpdateCropResponse{Crop: cropToProto(updated)}), nil
}

// DeleteCrop handles delete requests.
func (h *CropHandler) DeleteCrop(ctx context.Context, req *connect.Request[pb.DeleteCropRequest]) (*connect.Response[pb.DeleteCropResponse], error) {
	if req.Msg.GetId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "id is required")
	}
	if err := h.svc.DeleteCrop(ctx, req.Msg.GetId()); err != nil {
		return nil, errors.ToConnectError(err)
	}
	return connect.NewResponse(&pb.DeleteCropResponse{Success: true}), nil
}

func cropToProto(e *domain.Crop) *pb.Crop {
	return &pb.Crop{
		Id:       e.UUID,
		TenantId: e.TenantID,
		Name:     e.Name,
	}
}
